package dev.aether.api.common;
import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.validation.FieldError;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.ExceptionHandler;import org.springframework.web.bind.annotation.RestControllerAdvice;import java.util.Map;import java.util.stream.Collectors;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(MethodArgumentNotValidException.class) public ResponseEntity<Map<String,Object>> validation(MethodArgumentNotValidException exception){Map<String,String> errors=exception.getBindingResult().getFieldErrors().stream().collect(Collectors.toMap(FieldError::getField,FieldError::getDefaultMessage,(a,b)->a));return ResponseEntity.badRequest().body(Map.of("message","Validation failed","details",errors));}@ExceptionHandler(IllegalArgumentException.class) public ResponseEntity<Map<String,String>> badRequest(IllegalArgumentException exception){HttpStatus status=exception.getMessage()!=null&&exception.getMessage().equals("Lead not found")?HttpStatus.NOT_FOUND:HttpStatus.BAD_REQUEST;return ResponseEntity.status(status).body(Map.of("message",exception.getMessage()==null?"Invalid request":exception.getMessage()));} }
